void Solver::bump_var(int var, double coeff) {
    // Compute the increment for this variable
    double delta = var_inc * coeff;
    activity[var] += delta;

    // If any activity becomes excessively large, rescale all activities
    const double OVERFLOW_LIMIT = 1e150;
    if (activity[var] > OVERFLOW_LIMIT) {
        double scale = 1e-150;
        for (int i = 1; i <= vars; ++i) {
            activity[i] *= scale;
        }
        var_inc *= scale;
    }

    // Keep the VSIDS heap consistent
    if (vsids.inHeap(var)) {
        vsids.update(var);
    }
}
